// Brand images inlined as base64 data URIs at build time.
//
// IMPORTANT: these are NOT read from disk at request time on purpose.
// Netlify Functions run from a packaged bundle (/var/task) that does
// NOT include the public/ folder alongside the function code — public
// assets are served separately via Netlify's CDN. Reading them with
// fs.readFileSync(path.join(process.cwd(), "public", ...)) at request
// time works fine locally but throws ENOENT in production on Netlify,
// which is what broke every PDF/Word export. Inlining the (small,
// <20KB each) brand images directly as source-code constants removes
// the filesystem dependency entirely, so it works the same everywhere.
//
// If you ever need to swap one of these images: replace the file in
// public/brand/, then regenerate this file (base64-encode the PNG and
// paste the string in below) rather than editing the base64 by hand.

export const logoDataUri = "data:image/png;base64,";

export const badgeDataUri = "data:image/png;base64,";

export const badgeIconDataUri = "data:image/png;base64,";

export const signaturePascalDataUri = "data:image/png;base64,";

export const signatureCeliaDataUri = "data:image/png;base64,";
